import{_ as a,o as i,c as e,a2 as t}from"./chunks/framework.CZqXuAiL.js";const k=JSON.parse('{"title":"Installation","description":"Install Trash Bin Pro on a Pterodactyl panel via Blueprint or the standalone installer, verify the install, upgrade from v1.0.0/v1.0.1, and uninstall cleanly.","frontmatter":{"title":"Installation","description":"Install Trash Bin Pro on a Pterodactyl panel via Blueprint or the standalone installer, verify the install, upgrade from v1.0.0/v1.0.1, and uninstall cleanly."},"headers":[],"relativePath":"trash-bin-pro/getting-started/installation.md","filePath":"trash-bin-pro/getting-started/installation.md","lastUpdated":null}'),n={name:"trash-bin-pro/getting-started/installation.md"};function l(r,s,o,h,p,d){return i(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><p>Trash Bin Pro ships in two flavors that install the <strong>same</strong> panel code:</p><ol><li><strong>Blueprint extension</strong> (recommended) — <code>pterodactyltrashbinpro-v1.0.2.blueprint</code>.</li><li><strong>Standalone installer</strong> — copies <code>PanelFiles</code> into your panel and runs the idempotent patchers directly.</li></ol><p>Both paths patch the panel&#39;s PHP backend and the React/TypeScript client SPA, register the service provider, and run migrations. The client SPA <strong>must be rebuilt</strong> after either path or the Trash UI will not appear.</p><hr><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>Pterodactyl Panel <strong>v1.11.x / v1.12.x</strong> (Laravel 11, PHP 8.2+)</li><li><strong>Python 3</strong> — the patchers are Python scripts</li><li><strong>Node.js + Yarn</strong> — to rebuild the client SPA after install</li><li><a href="https://blueprint.zip" target="_blank" rel="noreferrer">Blueprint</a> <code>beta-2026-05</code> — Blueprint path only</li><li>Working <strong>scheduler cron</strong>: <code>* * * * * php /var/www/pterodactyl/artisan schedule:run</code> — the hourly purge is scheduled via the service provider, so it needs the stock panel scheduler running</li></ul><h2 id="back-up-first" tabindex="-1">Back up first <a class="header-anchor" href="#back-up-first" aria-label="Permalink to &quot;Back up first&quot;">​</a></h2><p>Trash Bin Pro patches core panel files (<code>FileController.php</code>, <code>Server.php</code>, <code>Permission.php</code>, <code>routes/api-client.php</code>, and a dozen SPA files). Take a full backup before installing:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/www/pterodactyl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/www/pterodactyl.bak</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mysqldump</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> root</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pterodactyl</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pterodactyl.sql.bak</span></span></code></pre></div><div class="danger custom-block"><p class="custom-block-title">Do not skip the backup</p><p>The patchers fail loudly and refuse to rebuild on anchor mismatches, but a backup is the only way to undo a half-patched panel quickly.</p></div><hr><h2 id="blueprint-install-recommended" tabindex="-1">Blueprint Install (recommended) <a class="header-anchor" href="#blueprint-install-recommended" aria-label="Permalink to &quot;Blueprint Install (recommended)&quot;">​</a></h2><p>Place <code>pterodactyltrashbinpro-v1.0.2.blueprint</code> in <code>/var/www/pterodactyl</code> (or your custom panel path), then:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/www/pterodactyl</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">blueprint</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pterodactyltrashbinpro-v1.0.2</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yarn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build:production</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">Older Node versions</p><p>If the production build fails with OpenSSL errors, your Node is too old for the panel&#39;s webpack toolchain:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">NODE_OPTIONS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">--openssl-legacy-provider</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> yarn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build:production</span></span></code></pre></div></div><h2 id="standalone-install-no-blueprint" tabindex="-1">Standalone Install (no Blueprint) <a class="header-anchor" href="#standalone-install-no-blueprint" aria-label="Permalink to &quot;Standalone Install (no Blueprint)&quot;">​</a></h2><p>Download the release and use the <code>standalone/</code> folder:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1. Copy the addon files into the panel</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PANEL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/var/www/pterodactyl</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -a</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/standalone/PanelFiles/.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PANEL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2. Run the installer</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PTERODACTYL_DIRECTORY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PANEL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/standalone/data/install.sh</span></span></code></pre></div><p>The installer:</p><ul><li>Patches <code>FileController.php</code>, <code>Server.php</code>, <code>FileObjectTransformer.php</code>, <code>Permission.php</code>, and <code>routes/api-client.php</code> — all idempotent, safe to re-run.</li><li>Registers <code>TrashBinProServiceProvider</code> in <code>config/app.php</code>.</li><li>Patches all React/TypeScript client SPA files.</li><li>Clears caches and runs migrations.</li></ul><p>Then rebuild the SPA:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PANEL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yarn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build:production</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># If your Node version requires it:</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># NODE_OPTIONS=--openssl-legacy-provider yarn build:production</span></span></code></pre></div><div class="info custom-block"><p class="custom-block-title">Re-running is safe</p><p>Every patch block is marker-guarded (<code>// pterodactyltrashbinpro</code>) with a per-block presence check. Re-running the installer is a zero-diff no-op unless something is actually missing, in which case it fails loudly instead of double-inserting.</p></div><hr><h2 id="post-install-verification" tabindex="-1">Post-Install Verification <a class="header-anchor" href="#post-install-verification" aria-label="Permalink to &quot;Post-Install Verification&quot;">​</a></h2><ol><li><strong>Admin panel loads</strong> — open <strong>Admin → Trash Bin Pro</strong> (<code>/admin/trashbinpro</code>). Configure global retention and capacity here.</li><li><strong>Trash toolbar button</strong> — open any server&#39;s file manager. A <strong>Trash</strong> button appears in the toolbar next to Upload / New File; clicking it opens the Trash view.</li><li><strong>Sub-user permission</strong> — <strong>trashbinpro.access</strong> is now available on the sub-user management page.</li><li><strong><code>.trash</code> stays hidden</strong> — the <code>.trash</code> folder is filtered out of normal file listings; users only see it through the Trash view.</li><li><strong>Soft delete works</strong> — delete a test file, confirm it appears in the Trash view, restore it, and confirm it returns to its original path.</li><li><strong>Purge scheduled</strong> — <code>php artisan list trashbin</code> should show <code>p:trashbin:purge</code>; it runs hourly through the scheduler.</li></ol><hr><h2 id="upgrading-from-v1-0-0-v1-0-1" tabindex="-1">Upgrading from v1.0.0 / v1.0.1 <a class="header-anchor" href="#upgrading-from-v1-0-0-v1-0-1" aria-label="Permalink to &quot;Upgrading from v1.0.0 / v1.0.1&quot;">​</a></h2><p>Install the new release over the top (Blueprint package or standalone files), then re-run the frontend patcher and rebuild:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PTERODACTYL_DIRECTORY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/var/www/pterodactyl</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/standalone/data/patch-frontend.py</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/www/pterodactyl</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yarn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build:production</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">The faTrash repair</p><p>v1.0.0/v1.0.1 patched the <code>faTrash</code> icon import with an anchored search that could be <strong>silently skipped</strong> on panels whose stock files were modified by themes or other addons — producing a white-screen <code>faTrash is not defined</code> error in the file manager. v1.0.2 uses anchor-free import merging: it merges into an existing <code>import { ... } from &#39;@fortawesome/free-solid-svg-icons&#39;</code> or inserts a new import line, and validates that every patched symbol has a matching import. Re-running <code>patch-frontend.py</code> from v1.0.2 repairs the broken import; you do not need to hand-edit any TSX file.</p></div><hr><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Cause</th><th>Fix</th></tr></thead><tbody><tr><td>Patcher prints <code>FAILED</code> and exits 1</td><td>Anchor mismatch — a stock panel file was modified by a theme, another addon, or a panel update</td><td><strong>Do not rebuild.</strong> The patcher stops before leaving a broken state. Restore the file from your backup or a clean panel copy, re-run the installer, then build</td></tr><tr><td>Build succeeds but no Trash button in the file manager</td><td>Stale built assets — the SPA was not rebuilt (or the browser cached the old bundle)</td><td><code>php artisan view:clear</code>, then hard-refresh the browser (Ctrl+Shift+R). Confirm <code>yarn build:production</code> completed without errors</td></tr><tr><td><code>422 Unprocessable Content</code> on Empty Trash</td><td>Leftover v1.0.0 patch — the endpoint was bound to a request class that requires a <code>files</code> body</td><td>Re-run the v1.0.2 patchers (Blueprint reinstall or <code>install.sh</code> / <code>patch-file-controller.py</code>) and rebuild the SPA</td></tr><tr><td><code>403</code> when opening the Trash view</td><td>Missing sub-user permission</td><td>Grant <strong>trashbinpro.access</strong> on the sub-user management page. Server owners always have it</td></tr></tbody></table><hr><h2 id="uninstall" tabindex="-1">Uninstall <a class="header-anchor" href="#uninstall" aria-label="Permalink to &quot;Uninstall&quot;">​</a></h2><p><strong>Standalone:</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PTERODACTYL_DIRECTORY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/var/www/pterodactyl</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/standalone/data/remove.sh</span></span></code></pre></div><p>The remover strips the service provider registration and every marker-guarded patch block from the PHP and SPA files. Afterwards:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/www/pterodactyl</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yarn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build:production</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # rebuild the SPA without the Trash UI</span></span></code></pre></div><p><strong>Blueprint:</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">blueprint</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -remove</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pterodactyltrashbinpro</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/www/pterodactyl</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yarn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build:production</span></span></code></pre></div><p><strong>Optional full cleanup:</strong></p><ul><li>Delete the merged <code>PanelFiles</code> the remover does not touch: <code>app/Services/TrashBinPro/</code>, <code>app/Models/TrashBinPro/</code>, <code>app/Console/Commands/TrashBinPro/</code>, <code>app/Providers/TrashBinProServiceProvider.php</code>, <code>config/trashbinpro.php</code>, <code>routes/admin-trashbinpro.php</code>, <code>resources/views/admin/trashbinpro/</code>, <code>lang/en/trashbinpro.php</code>, and the new SPA API files (<code>restoreFiles.ts</code>, <code>emptyTrash.ts</code>, <code>getTrashQuota.ts</code>).</li><li>Drop the database tables. This is destructive and deletes all trash history:</li></ul><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">DROP</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> TABLE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> IF</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> EXISTS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> trashbin_files, trashbin_settings, trashbin_egg_settings, trashbin_server_settings;</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">Files in <code>/.trash</code> are not removed</p><p>Uninstalling does not delete the <code>.trash</code> folders on your game servers. Empty the Trash Bin from the panel (or delete <code>/.trash</code> via SFTP/Wings) <strong>before</strong> removing the addon, or the files simply stay on disk and keep counting against server quotas.</p></div>`,47)])])}const g=a(n,[["render",l]]);export{k as __pageData,g as default};
